def main():
 draft=A/'ABJURATION_CONJURATION_RANK4_OPERATING_PROPOSALS.json';out=R/'data/director/spell_proposals/abjuration_conjuration_rank4.json';doc=R/'docs/spells/proposals/ABJURATION_CONJURATION_RANK4.md';receipt=A/'ABJURATION_CONJURATION_RANK4_OPERATING_PROPOSAL_CHECK.json'
 assert not any(p.exists() for p in [draft,out,doc,receipt]),'Preserve prior artifacts before revision'
 prep_path=A/'ABJURATION_CONJURATION_RANK4_SOURCE_PREPARATION.json';prep=read(prep_path);selected={x['spellId']:x for x in prep['selectedSpells']}
 cat_path=R/'data/public/spell_playtests/catalog.json';cat=read(cat_path);by={x['id']:x for x in cat['spells']}
 idx_path=cat_path.with_name('authored_review_index.json');idx=read(idx_path);entries={x['id']:x for x in idx['entries']}
 checks=[]
 def check(n,v):checks.append({'name':n,'pass':bool(v)});assert v,n
 check('Exactly15mechanical proposals plus deferred Banishment',len(P)==15 and {x['spellId'] for x in P}==set(selected)-{'banishment'})
 check('412reviewed436pending ordinaryspells remain',len(by)==848 and idx['authoredCounts']=={'reviewed':412,'pending':436})
 records=[]
 for p in P:
  s=selected[p['spellId']];actual=by[p['spellId']]
  check(p['spellId']+' completecurrentrecord identical to prepared source',actual==s['fullSourceAndCurrentAccessRecord'])
  check(p['spellId']+' remains pending',entries[p['spellId']]['authoredStatus']=='pending-authored-procedure')
  check(p['spellId']+' two authoredcases',len(p['workedCases'])==2)
  records.append({**p,'questionId':s['questionId'],'originalQuestion':s['individualQuestion'],'fullSourceAndCurrentAccessRecord':actual,'sourceRecordSha256':s['recordSha256'],'status':'unadopted-unsent-operating-proposal','examplesAreRuntimeTests':False})
 records.sort(key=lambda x:x['questionId'])
 ban=selected['banishment'];check('Banishment literalreceipt unchanged',ban['fullSourceAndCurrentAccessRecord']==by['banishment'] and ban['scope']=='post-push receipt only')
 check('ClericAlignmentAnchor rank7base17 retained',by['alignment-anchor']['classAccess']['Cleric']['rank']==7 and by['alignment-anchor']['classAccess']['Cleric']['baseRpCost']==17)
 check('DruidAlignmentAnchor rank4base7 retained',by['alignment-anchor']['classAccess']['Druid']['rank']==4 and by['alignment-anchor']['classAccess']['Druid']['baseRpCost']==7)
 inputs={cat_path,idx_path,prep_path,R/'data/playtest/bestiary_public_source_candidate.json'}
 counterparts=[]
 for old in prep['completeCounterparts']:
  sid=old['id'];e=entries[sid];f=cat_path.parent/e['procedureFile'];d=read(f);inputs.add(f)
  for k in e['wholeCardPointer'].strip('/').split('/'):d=d[int(k)] if isinstance(d,list) else d[k]
  counterparts.append({'id':sid,'preparedCompleteRecord':old,'currentSourceCatalogRecord':by[sid],'currentAuthoredIndexEntry':e,'completeCurrentAuthoredRecord':d})
 guides={}
 for x in prep['currentGoverningExcerpts']:
  p=G/x['file'];inputs.add(p)
